#include "sensors/bh1750.h"

#include <stddef.h>

/* bh1750_ok: the status of a call that completed every step. */
static bh1750_status bh1750_ok(void)
{
    bh1750_status s = {{I2C_STATUS_OK, 0, 0, 0}, BH1750_STAGE_NONE};
    return s;
}

/* bh1750_failed: the status for a step that failed with io. */
static bh1750_status bh1750_failed(i2c_result io, bh1750_stage stage)
{
    bh1750_status s;

    s.io = io;
    s.stage = stage;
    return s;
}

/* bh1750_bad_argument: the status for a call refused before any I/O. */
static bh1750_status bh1750_bad_argument(void)
{
    i2c_result io = {I2C_STATUS_INVALID_ARGUMENT, 0, 0, 0};
    return bh1750_failed(io, BH1750_STAGE_ARGUMENT);
}

/*
 * device_usable: true if dev is open at one of the two addresses the
 * BH1750 can have, so its opcodes never go to another device on the bus.
 */
static int device_usable(const i2c_device *dev)
{
    return dev != NULL && dev->ops != NULL &&
           (dev->address_7bit == BH1750_ADDRESS_ADDR_LOW ||
            dev->address_7bit == BH1750_ADDRESS_ADDR_HIGH);
}

/* send_command: write one opcode as its own STOP-terminated transaction. */
 *   counts: the wrapper sets requested_len and transferred_len to 0.
 * - Interruption policies differ by operation. A read or write interrupted
 *   by a signal (EINTR) is reported as OS_ERROR/EINTR and not retried,
 *   because the backend cannot tell whether the transaction reached the
 *   bus; the caller decides. A wait is retried toward the deadline fixed
 *   before it first slept. A close is never retried.
 */

#define I2C_ADDRESS_7BIT_MAX 0x7f

typedef enum {
    I2C_STATUS_OK = 0,
    I2C_STATUS_INVALID_ARGUMENT,
    I2C_STATUS_OS_ERROR,        /* a system call failed; see os_errno */
    I2C_STATUS_SHORT_TRANSFER,  /* bytes moved differ from bytes requested,
                                   fewer or (backend bug) more */
    I2C_STATUS_SCRIPT_MISMATCH  /* mock only: operation not in the script */
} i2c_status;

typedef struct {
    i2c_status status;
    int os_errno;           /* errno captured right after the failed call */
    size_t requested_len;
    size_t transferred_len;
} i2c_result;

typedef struct {
    i2c_result (*write)(void *ctx, const uint8_t *buf, size_t len);
    i2c_result (*read)(void *ctx, uint8_t *buf, size_t len);
    i2c_result (*wait_us)(void *ctx, uint32_t duration_us);
    i2c_result (*close)(void *ctx);
